
use customer_behaviour;

USE customer_behaviour;

SELECT
    TABLE_SCHEMA,
    TABLE_NAME
FROM INFORMATION_SCHEMA.TABLES
WHERE TABLE_TYPE = 'BASE TABLE';

select * from dbo.customers;

-- 1] What is the total revenue generated by male vs female customers
select gender, sum(purchase_amount) as revenue from customers group by gender

-- 2] Which customer used a discount but still spent more than the average purcase amount
SELECT customer_id, purchase_amount
FROM customers
WHERE discount_applied = 'Yes'
AND purchase_amount > (
    SELECT AVG(CAST(purchase_amount AS DECIMAL(18,2)))
    FROM customers
);

-- 3] Which are the top 5 producrt with highest average review rating
select top 5 item_purchased, avg(review_rating) as 'Average Product Rating'
from customers
group by item_purchased order by AVG(review_rating) desc;

-- 4] Compaire the average Purchase amount between standarr and Express shipping
select shipping_type, avg(purchase_amount) from customers
where shipping_type in ('Standard', 'Express')
group by shipping_type;

-- 5] Do subscription customers spend more? Compaire average spend and total revene
-- between subscribers and non-subscribers
select subscription_status, count(customer_id) as total_customers,
avg(purchase_amount) as average_spend,
sum(purchase_amount) as total_revenue from customers
group by subscription_status 
order by total_revenue, average_spend desc;

--6] which 5 products have the highest percentage of purchases with discount applied?
select top 5 item_purchased,
round(100 * sum(case when discount_applied = 'Yes' then 1 else 0 end) / count(*),2) as discount_rate from customers  -- where we get discount %
group by item_purchased 
order by discount_rate desc;

--7 Segment customers into new, returning and loyal based on their total number of 
-- previous purchases and show the count of each segment.
with customer_type as (
    select customer_id,previous_purchases,
    case 
        when previous_purchases = 1 then 'New'
        when previous_purchases between 2 and 10 then 'Returning'
        else 'Loyal'
    end as customer_segment
    from customers
)
select customer_segment, count(*) as "Number of Customers" from customer_type
group by customer_segment;

-- 8 What are the top 3 most purchased products within each category?

with item_counts as (
select category, item_purchased, count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from customers
group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders from item_counts
where item_rank <= 3;